        u = Dummy('bivariate-cov')
        ueq = eq.subs(p, u)
        if not ueq.has_free(sym):
            sol = _vsolve(ueq, u, **flags)
            inv = _vsolve(p - u, sym)
            return [i.subs(u, s) for i in inv for s in sol]

    g = _filtered_gens(eq.as_poly(), sym)
    up_or_log = set()
    for gi in g:
